SELECT jsonb_build_object('name',item.name,'value',level.xx_hash) AS value FROM public.level level JOIN LATERAL (SELECT source.* FROM public.level_item source WHERE source.id_level=level.id AND source.deleted=false ORDER BY source.updated_at DESC,source.id DESC LIMIT 1) item ON true LEFT JOIN public."user" author ON author.steam_id=item.author_id WHERE level.publicly_visible=true AND (level.xx_hash ILIKE $1||'%' OR item.name ILIKE '%'||$1||'%' OR author.steam_name ILIKE '%'||$1||'%') ORDER BY (level.xx_hash=$1) DESC, (lower(item.name)=lower($1)) DESC,similarity(item.name,$1) DESC,level.id DESC LIMIT 25
